/* Shared application rules. Browser storage is used for the Part A simulation. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.MutiaraCore=api;})(typeof window!=='undefined'?window:this,function(){
  'use strict';
  const KEY='mutiara-feedback-v2';
  const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function validate(data){const errors={};if(!data.name||!data.name.trim()||data.name.trim().length>80)errors.name='Enter your name (up to 80 characters).';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email||'')||data.email.length>120)errors.email='Enter a valid email address.';if(!data.category)errors.category='Choose a concern category.';if(!data.location)errors.location='Choose the affected area.';const length=(data.description||'').trim().length;if(length<15||length>2000)errors.description='Describe your concern using 15–2,000 characters.';if(!data.consent)errors.consent='Please acknowledge how this prototype stores your feedback.';return errors;}
  function validRecord(r){return r&&typeof r.id==='string'&&/^MC-\d{4}-[A-Z0-9-]+$/.test(r.id)&&typeof r.description==='string'&&typeof r.created==='string'&&!Number.isNaN(Date.parse(r.created))&&Number.isInteger(r.status)&&r.status>=0&&r.status<=3&&Array.isArray(r.history)&&r.history.every(h=>h&&Number.isInteger(h.stage)&&h.stage>=0&&h.stage<=3&&typeof h.at==='string'&&!Number.isNaN(Date.parse(h.at))&&typeof h.note==='string')&&r.history.length===r.status+1&&r.history.every((h,i)=>h.stage===i)&&(r.messages===undefined||(Array.isArray(r.messages)&&r.messages.every(m=>m&&typeof m.text==='string'&&m.text.trim().length>=5&&m.text.length<=1000&&typeof m.at==='string'&&!Number.isNaN(Date.parse(m.at)))));}
  function read(storage){try{const raw=storage.getItem(KEY);if(!raw)return{records:[],error:null};const rows=JSON.parse(raw);if(!Array.isArray(rows)||!rows.every(validRecord))throw new Error('Invalid records');return{records:rows,error:null};}catch{return{records:[],error:'Saved records could not be loaded. Existing browser data was left unchanged.'};}}
  function save(storage,rows){if(!rows.every(validRecord))throw new Error('Invalid complaint data');storage.setItem(KEY,JSON.stringify(rows));}
  function reference(cryptoObject,now=new Date()){const bytes=new Uint8Array(6);if(!cryptoObject||typeof cryptoObject.getRandomValues!=='function')throw new Error('Secure reference generation is unavailable in this browser.');cryptoObject.getRandomValues(bytes);return`MC-${now.getFullYear()}-${Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('').toUpperCase()}`;}
  function create(data,id,now=new Date().toISOString()){const errors=validate(data);if(Object.keys(errors).length)throw new Error('Invalid feedback');return{id,name:data.name.trim(),email:data.email.trim(),category:data.category,location:data.location,landmark:(data.landmark||'').trim().slice(0,160),description:data.description.trim(),created:now,status:0,history:[{stage:0,at:now,note:'Feedback saved and reference assigned.'}]};}
  function advance(record,note,now=new Date().toISOString()){if(!validRecord(record))throw new Error('Invalid complaint record');if(record.status>=3)return record;const status=record.status+1;return{...record,status,history:[...record.history,{stage:status,at:now,note:((note||'').trim()||'Demonstration status updated by the simulated project team.').slice(0,400)}]};}
  function filterNotices(rows,{query='',area='',type='',phase='all',date='2026-11-02'}={}){return rows.filter(n=>(!query||(n.title+' '+n.summary+' '+n.area).toLowerCase().includes(query.trim().toLowerCase()))&&(!area||n.area===area)&&(!type||n.type===type)&&(phase==='all'||(phase==='upcoming'&&n.start>date)||(phase==='active'&&n.start<=date&&n.end>=date)||(phase==='archived'&&n.end<date)));}
  function sortNotices(rows,order='newest'){const copy=rows.slice(),rank={High:3,Moderate:2,Low:1};return copy.sort((a,b)=>order==='start'?a.start.localeCompare(b.start):order==='impact'?(rank[b.severity]-rank[a.severity]||a.start.localeCompare(b.start)):b.published.localeCompare(a.published)||a.id.localeCompare(b.id));}
  function filterCases(rows,{query='',status=''}={}){const q=query.trim().toLowerCase();return rows.filter(r=>(status===''||r.status===Number(status))&&(!q||[r.id,r.category,r.location,r.description].join(' ').toLowerCase().includes(q)));}
  function addMessage(record,text,now=new Date().toISOString()){if(!validRecord(record))throw new Error('Invalid complaint record');const value=text.trim();if(value.length<5||value.length>1000)throw new Error('Follow-up must contain 5–1,000 characters');return{...record,messages:[...(record.messages||[]),{text:value,at:now}]};}
  return{KEY,escapeHtml,validate,validRecord,read,save,reference,create,advance,filterNotices,sortNotices,filterCases,addMessage};
});
